function useConditionalFetch(shouldFetch) {
  if (!shouldFetch) {
    return null;
  }

  const [data, setData] = React.useState(null);

  React.useEffect(() => {
    fetch('/api/data').then(r => r.json()).then(setData);
  }, []);

  return data;
}

