function App() {
  const [urgent, setUrgent] = React.useState('');
  const [deferred, setDeferred] = React.useState('');
  const [isPending, startTransition] = React.useTransition();

  function handleChange(e) {
    setUrgent(e.target.value);
    startTransition(() => {
      setDeferred(e.target.value);
    });
  }

  return (
    <>
      <input onChange={handleChange} />
      <p>Urgent: {urgent}</p>
      {isPending ? 'Loading...' : <SlowList query={deferred} />}
    </>
  );
}

function ParentList({ items }) {
  const [selected, setSelected] = React.useState(
    items[0]
  );

  // When items prop changes from outside,
  // selected stays as the old value
  return (
    <>
      {items.map(item => (
        <button
          key={item.id}
          onClick={() => setSelected(item)}
          style={{ fontWeight: item.id === selected.id ? 'bold' : 'normal' }}
        >
          {item.name}
        </button>
      ))}
    </>
  );
}

